INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('45a9ba77-71a4-4698-82e6-1922716428ca', 'Dancinha TikTok 2', 'Dancinhas', 'From 0.0s to 0.8s, the person stands in a waist-up shot facing forward, raising both hands to rest on her waist. From 0.8s to 4.8s, she keeps her hands resting on her hips while smiling warmly toward the camera. From 4.8s to 6.0s, she lowers her arms to her sides and tilts her head and upper body to the right. From 6.0s to 7.0s, she forcefully flips her head to the left, whipping her hair into the air. From 7.0s to 7.8s, she returns head upright as her hair settles, smiling at the camera. The framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/45a9ba77-71a4-4698-82e6-1922716428ca.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/45a9ba77-71a4-4698-82e6-1922716428ca.jpg', 22, TRUE, '2026-06-15T18:55:28.580052+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', NULL, FALSE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/45a9ba77-71a4-4698-82e6-1922716428ca-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('eaa434ea-427b-474f-930c-163abc339b7f', 'Natural Idle Loop Feel', 'Movimentos', 'From 0.0s to 1.2s, the person stands facing forward, raising both hands to rest firmly on their waist with elbows bent outward, maintaining a direct gaze and broad smile toward the camera. From 1.2s to 7.8s, the person holds this hands-on-hips pose continuously, keeping their head centered with slight natural breathing motions and subtle micro-nods while holding a confident smile straight ahead. The waist-up framing remains fixed and static throughout the entire clip without any camera movement.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/eaa434ea-427b-474f-930c-163abc339b7f.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/eaa434ea-427b-474f-930c-163abc339b7f.jpg', 7, TRUE, '2026-06-15T18:54:33.769865+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/eaa434ea-427b-474f-930c-163abc339b7f-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('7289adaf-3feb-43b7-8ff0-93044633bb71', 'Ajuste em uma única etapa', 'Movimentos', 'In a waist-up framing, from 0.0s to 1.8s, the person turns her hips and body to her right while keeping her face turned toward the camera with a big smile. From 1.8s to 3.5s, she rotates fully around to her left side, glancing back over her shoulder while continuing to smile. From 3.5s to 4.8s, she swivels back to face the camera directly and brings both hands up to rest on her hips. From 4.8s to 7.8s, she holds the pose with hands on her waist as the camera slowly pushes in.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/7289adaf-3feb-43b7-8ff0-93044633bb71.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/7289adaf-3feb-43b7-8ff0-93044633bb71.jpg', 4, TRUE, '2026-06-15T18:54:24.16234+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'push_in', 'The camera slowly pushes in from 4.8s to 7.8s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/7289adaf-3feb-43b7-8ff0-93044633bb71-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('d95d5264-ed25-433a-a27b-3947c37c1fca', 'Soft Push-Out', 'Movimentos', 'From 0.0s to 1.5s, the person walks forward toward the camera with a steady smile, tightening the framing to a waist-up shot. From 1.5s to 3.0s, she rests her right hand against her lower torso and turns her hips and chest slightly to the right while looking straight into the lens. From 3.0s to 4.5s, the camera slowly pulls out as she brings her left hand inward to meet her right hand at waist height. From 4.5s to 7.8s, she holds her hands clasped together near her stomach, gently swaying her hips from side to side while smiling directly forward.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/d95d5264-ed25-433a-a27b-3947c37c1fca.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/d95d5264-ed25-433a-a27b-3947c37c1fca.jpg', 8, TRUE, '2026-06-15T18:54:37.993766+00:00', 'frontal', 'full-body', 'worn', TRUE, 'pull_out', 'The camera slowly pulls out from 3.0s to 5.0s to widen the framing.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/d95d5264-ed25-433a-a27b-3947c37c1fca-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('ea3e3ecd-df57-4de9-884d-6d6bb1ab0b11', 'Micro Zoom + Pausa', 'Movimentos', 'From 0.0s to 1.0s, in a waist-up shot, the person stands facing forward. From 1.0s to 2.0s, the camera slowly pushes in closer to a bust-level framing while she places her left hand over the front of her handbag at her waist. From 2.0s to 5.0s, she holds the pose, swaying her torso subtly while looking towards the camera with a confident gaze. From 5.0s to 7.833s, she tilts her head slightly back and holds the posture, maintaining her left hand resting on the purse while her hips shift gently.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/ea3e3ecd-df57-4de9-884d-6d6bb1ab0b11.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/ea3e3ecd-df57-4de9-884d-6d6bb1ab0b11.jpg', 14, TRUE, '2026-06-15T18:54:57.350815+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'push_in', 'The camera performs a slow push-in from 1.0s to 2.0s, then holds.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/ea3e3ecd-df57-4de9-884d-6d6bb1ab0b11-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('05e68626-d304-4c76-83bf-5b7fb0e8f8e1', 'Ajustando Óculos/Acessório', 'Movimentos', 'From 0.0s to 1.3s, the person stands full-body, facing front with arms relaxed at their sides, chin slightly elevated and gaze directed upward. From 1.3s to 5.7s, they tilt their head down, shifting their gaze to their left wrist while bringing their right arm across the torso to adjust a wrist accessory with their fingers. From 5.7s to 7.8s, they lift their head back up to look forward, lower their arms to their sides, and return to an upright posture. Simultaneously, from 0.0s to 4.5s, the camera slowly pushes in toward the torso, then gently pulls back out by 7.8s.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/05e68626-d304-4c76-83bf-5b7fb0e8f8e1.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/05e68626-d304-4c76-83bf-5b7fb0e8f8e1.jpg', 46, TRUE, '2026-06-15T18:56:51.762687+00:00', 'frontal', 'full-body', 'worn', FALSE, 'push_in', 'From 0.0s to 4.5s, the camera slowly pushes in toward the torso, then gently pulls back out by 7.8s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/05e68626-d304-4c76-83bf-5b7fb0e8f8e1-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('0ca0fe3c-92b5-45ac-b54b-af773acaa4e8', 'Selfie Cabelo', 'Selfie', 'Framing is a head-and-shoulders selfie shot. From 0.0s to 1.167s, the subject smiles at the camera while briefly holding her left jacket lapel. From 1.167s to 2.667s, she raises her left hand to rest on top of her beanie, tilting her head right with eyes closed in a warm smile. From 2.667s to 4.167s, her left hand pats her beanie in a rhythmic gesture. From 4.167s to 5.000s, her fingers run through her hair, tossing it back. From 5.000s to 7.833s, she lowers her hand and speaks continuously with expressive facial movements. Subtle handheld motion occurs throughout.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/0ca0fe3c-92b5-45ac-b54b-af773acaa4e8.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/0ca0fe3c-92b5-45ac-b54b-af773acaa4e8.jpg', 40, TRUE, '2026-06-15T18:56:29.152572+00:00', 'frontal', 'head-and-shoulders', 'worn', TRUE, 'handheld', 'The camera exhibits slight natural handheld shake throughout the clip.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/0ca0fe3c-92b5-45ac-b54b-af773acaa4e8-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('3ac1634d-d7ed-428f-9a15-959921943087', 'Dancinha TikTok 1', 'Dancinhas', 'From 0.0s to 0.6s, the person smiles at the camera while bringing hands up from waist height toward the chest. From 0.6s to 1.5s, they tap near their chest before raising open palms beside the head. From 1.5s to 4.3s, they reach overhead into their hair, running fingers through it and tossing it repeatedly while swaying their head and hips side to side. From 4.3s to 6.0s, they drop arms wide and swing their hips energetically. From 6.0s to 7.8s, they raise both hands into peace signs near their eyes, smiling broadly before opening their arms wide.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/3ac1634d-d7ed-428f-9a15-959921943087.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/3ac1634d-d7ed-428f-9a15-959921943087.jpg', 23, TRUE, '2026-06-15T18:55:35.301252+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', '{"beats": [{"end_s": 1.5, "start_s": 0, "description": "The person brings hands up to tap the chest before raising open palms beside the head.", "is_defining": false}, {"end_s": 4.3, "start_s": 1.5, "description": "They reach overhead into their hair, running fingers through and tossing it repeatedly while swaying their head and hips from screen left to screen right.", "is_defining": true}, {"end_s": 6, "start_s": 4.3, "description": "They drop their arms wide, swinging their hips energetically.", "is_defining": false}, {"end_s": 7.8, "start_s": 6, "description": "They flash peace signs near their eyes, then open both arms wide.", "is_defining": false}], "continuity": null}'::jsonb, FALSE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/3ac1634d-d7ed-428f-9a15-959921943087-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('576bb82d-184c-4259-aef5-a46ee302446c', 'POV - Capinha', 'POV', 'From 0.0s to 1.0s, a hand holds a phone upright facing directly toward the camera in a close-up framing. From 1.0s to 2.5s, the hand slowly tilts and turns the phone to the left and back, letting light glint off its surface. From 2.5s to 4.8s, the hand tilts the phone side to side in subtle rocking motions to showcase the back design from different angles. From 4.8s to 7.8s, the fingertips lightly tap their long nails repeatedly against the back cover of the phone, alternating rhythmically.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/576bb82d-184c-4259-aef5-a46ee302446c.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/576bb82d-184c-4259-aef5-a46ee302446c.jpg', 24, TRUE, '2026-06-15T18:55:40.016629+00:00', 'pov', 'hands', 'held', FALSE, 'static', 'the framing never changes', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/576bb82d-184c-4259-aef5-a46ee302446c-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('5804e10f-96d7-459e-a465-fb40a9b22d52', 'Espelho Confiança', 'Mirror Selfie', 'In a waist-up mirror selfie from 0.0s to 0.5s, she holds a phone in her right hand while smiling into her reflection. From 0.5s to 2.0s, she raises her left hand to run her fingers through the left side of her hair, smoothing it back while gently tilting her head. From 2.0s to 2.8s, her left hand glides down her torso back to the desk. From 2.8s to 4.8s, as the framing tightens, she tilts her head slightly and shifts her gaze to her phone screen. From 4.8s to 7.8s, she looks back into the lens, smiling and softly speaking with her left arm resting on the table.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/5804e10f-96d7-459e-a465-fb40a9b22d52.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/5804e10f-96d7-459e-a465-fb40a9b22d52.jpg', 42, TRUE, '2026-06-15T18:56:35.684674+00:00', 'mirror', 'waist-up', 'worn', TRUE, 'push_in', 'From 2.8s to 4.0s, the camera slowly pushes in closer to a head-and-shoulders framing, where it stays static until 7.8s.', '{"beats": [{"end_s": 2, "start_s": 0, "description": "Holding a phone on screen left while smiling, she raises her hand on screen right to run her fingers through her hair, smoothing it back with a subtle head tilt.", "is_defining": true}, {"end_s": 4.8, "start_s": 2, "description": "Her hand glides down her torso to the desk, after which she tilts her head and shifts her gaze down to the phone.", "is_defining": false}, {"end_s": 7.8, "start_s": 4.8, "description": "She looks back up at her reflection, smiling and speaking softly.", "is_defining": false}], "continuity": "A phone is held in the hand on screen left throughout."}'::jsonb, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/5804e10f-96d7-459e-a465-fb40a9b22d52-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('c0028842-1927-46e2-9b71-9a5adb21f6c7', 'Movimento Rítmico + Apontar', 'CTA', 'From 0.0s to 3.0s, in a waist-up framing, the person smiles warmly at the camera while rhythmically swaying hips side to side and swinging both arms fluidly back and forth with light torso movement. From 3.0s to 6.6s, the person raises both arms, bends elbows, and points both index fingers downward toward the lower frame, pulsing hands up and down repeatedly in rhythm while maintaining gaze. From 6.6s to 7.8s, arms drop to the sides while hips shift left and right before settling back into a centered stance. The camera remains completely static throughout.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/c0028842-1927-46e2-9b71-9a5adb21f6c7.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/c0028842-1927-46e2-9b71-9a5adb21f6c7.jpg', 27, TRUE, '2026-06-15T18:55:46.970808+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/c0028842-1927-46e2-9b71-9a5adb21f6c7-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('f2c1cd14-e8eb-48c1-92de-8cd278e70c5a', 'Revelação e Admiração', 'Movimentos', 'From 0.0s to 1.5s, in a waist-up mirror framing, the person holds a phone up with their right hand while smiling directly into their reflection, keeping their left hand down. From 1.5s to 3.5s, they lift their left hand to run their fingers through their hair on the side, turning their head slightly right while maintaining a warm smile toward the mirror. From 3.5s to 5.5s, they continue stroking down their hair strands before bringing their left hand lower. From 5.5s to 7.8s, the left hand rests near their hip while they tilt their head subtly and pose for the mirror. The camera remains completely static throughout.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/f2c1cd14-e8eb-48c1-92de-8cd278e70c5a.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/f2c1cd14-e8eb-48c1-92de-8cd278e70c5a.jpg', 34, TRUE, '2026-06-15T18:56:08.849618+00:00', 'mirror', 'waist-up', 'worn', TRUE, 'static', 'The camera framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/f2c1cd14-e8eb-48c1-92de-8cd278e70c5a-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('2e7232bf-fbc1-4c63-84cf-48f7ea1a3ca1', 'Câmera estática + movimento corporal', 'Movimentos', 'In a waist-up shot, the camera remains static throughout. From 0.0s to 1.1s, the subject sways hips softly side-to-side while bringing both hands inward from her thighs to rest against her waist-level accessory. From 1.1s to 4.3s, she tilts her head distinctly to her left with gaze locked forward, keeping her hands resting together over the front accessory. From 4.3s to 5.1s, she brings her head back upright, lifts her chin slightly, and lowers both arms to her sides. From 5.1s to 7.8s, she stands tall facing forward with arms resting by her sides, performing subtle hip sways.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/2e7232bf-fbc1-4c63-84cf-48f7ea1a3ca1.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/2e7232bf-fbc1-4c63-84cf-48f7ea1a3ca1.jpg', 17, TRUE, '2026-06-15T18:55:05.739176+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'the framing never changes', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/2e7232bf-fbc1-4c63-84cf-48f7ea1a3ca1-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('b8d9e3f5-aebd-42a8-9b06-b7fd61f6974b', 'POV - Sapatos', 'POV', 'From 0.0s to 1.5s, a hand holding the product rotates it roughly 90 degrees to the right, smoothly presenting its side profile to the camera. From 1.5s to 3.0s, the hand holds the side view steady before slowly turning the product back toward center. From 3.0s to 5.2s, the hand continues rotating the product counter-clockwise until its front side directly faces the lens. From 5.2s to 7.833s, the hand holds the product still in front position before slightly tilting it back toward the right angle.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b8d9e3f5-aebd-42a8-9b06-b7fd61f6974b.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b8d9e3f5-aebd-42a8-9b06-b7fd61f6974b.jpg', 25, TRUE, '2026-06-15T18:55:42.440241+00:00', 'pov', 'hands', 'held', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b8d9e3f5-aebd-42a8-9b06-b7fd61f6974b-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('6b282a42-90de-48d6-b588-32f1c591a797', 'Foco de movimento assimétrico', 'Movimentos', 'From 0.0s to 2.0s, the person stands facing the camera in a three-quarter framing, holding a warm smile and gazing directly forward. The right hand rests on the right hip with the elbow bent outward, while the left arm hangs by the side. From 2.0s to 4.5s, the person sways their hips smoothly from side to side and tilts their head slightly to the left while keeping eye contact. From 4.5s to 5.0s, they switch arms, lowering the right hand to the side and placing the left hand onto the left hip. From 5.0s to 7.8s, they hold this new pose with subtle body movements.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/6b282a42-90de-48d6-b588-32f1c591a797.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/6b282a42-90de-48d6-b588-32f1c591a797.jpg', 2, TRUE, '2026-06-15T18:54:17.382353+00:00', 'frontal', 'full-body', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/6b282a42-90de-48d6-b588-32f1c591a797-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('b6921807-6cc1-4d0d-b0d7-5517f51ced6c', 'Destaque de Tecido', 'Movimentos', 'From 0.0s to 0.8s, the person stands facing forward with hands at their sides, smiling directly at the camera. From 0.8s to 2.5s, they bring both hands up to grasp the lapels of their jacket at chest height, holding them while maintaining eye contact. From 2.5s to 4.3s, their hands slide down along the front edges to the waist while their gaze briefly dips before returning to the camera. From 4.3s to 6.1s, they release the jacket, drop their arms, and turn away to face backward while looking over their left shoulder. From 6.1s to 7.8s, they pivot smoothly back to face the camera frontally.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b6921807-6cc1-4d0d-b0d7-5517f51ced6c.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b6921807-6cc1-4d0d-b0d7-5517f51ced6c.jpg', 35, TRUE, '2026-06-15T18:56:11.316315+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b6921807-6cc1-4d0d-b0d7-5517f51ced6c-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('b9caff82-f72f-4109-b5f4-78db35484036', 'Passando a Mão no Cabelo', 'Movimentos', 'From 0.0s to 0.7s, the person stands in a full-body frontal stance, holding a still posture with arms resting at their sides. From 0.7s to 1.3s, they raise their right hand upward toward their head. From 1.3s to 6.2s, they place their right hand on top of their head, lightly running fingers through their hair while subtly tilting their head right and keeping their gaze fixed forward. From 6.2s to 6.8s, they lower their right arm smoothly back to their side. From 6.8s to 7.8s, they hold a stable stance facing forward with chin slightly lifted. The framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b9caff82-f72f-4109-b5f4-78db35484036.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b9caff82-f72f-4109-b5f4-78db35484036.jpg', 48, TRUE, '2026-06-15T18:56:58.064556+00:00', 'frontal', 'full-body', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b9caff82-f72f-4109-b5f4-78db35484036-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('feafa378-8c1f-44f4-8345-3117b60b5c45', 'Micro Sorriso', 'Movimentos', 'From 0.0s to 2.5s, the person poses facing forward, holding their right hand resting against their hip while the left arm hangs down naturally, maintaining a warm, confident smile directed straight at the camera. From 2.5s to 5.0s, they keep their posture steady with gentle breathing, making slight eye blinks while their head tilts almost imperceptibly to the left. From 5.0s to 7.8s, they tilt their head slightly to the right with a soft, slow eye blink, before returning their gaze directly toward the lens with a serene smile.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/feafa378-8c1f-44f4-8345-3117b60b5c45.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/feafa378-8c1f-44f4-8345-3117b60b5c45.jpg', 0, TRUE, '2026-06-15T18:54:12.488417+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', '{"beats": [{"end_s": 2, "start_s": 0, "description": "The subject stands in a waist-up pose with a hand resting on her hip at screen left, maintaining a warm smile and looking directly forward.", "is_defining": false}, {"end_s": 4.5, "start_s": 2, "description": "She tilts her head slightly toward screen right and holds a relaxed posture while keeping her warm smile.", "is_defining": true}, {"end_s": 6.3, "start_s": 4.5, "description": "Her head slowly re-centers.", "is_defining": false}, {"end_s": 7.8, "start_s": 6.3, "description": "She tilts her chin slightly upward before settling back into her smile.", "is_defining": false}], "continuity": "The hand at screen left remains resting on the hip throughout."}'::jsonb, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/feafa378-8c1f-44f4-8345-3117b60b5c45-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('ff7b9d58-eb20-4c88-9b98-86446a10489c', 'POV - Produto Pequeno', 'POV', 'From 0.0s to 1.0s, a single left hand holds the product upright in front of the camera, fingers supporting its base. From 1.0s to 2.0s, the wrist turns smoothly to tilt the product about forty-five degrees to the right, angling its side profile into view. From 2.0s to 3.0s, the hand rotates the product back to its original position facing straight ahead. From 3.0s to 7.8s, the hand presents the product stationary in the foreground with steady focus, maintaining a clear display until the clip ends.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/ff7b9d58-eb20-4c88-9b98-86446a10489c.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/ff7b9d58-eb20-4c88-9b98-86446a10489c.jpg', 26, TRUE, '2026-06-15T18:55:44.541895+00:00', 'pov', 'hands', 'held', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/ff7b9d58-eb20-4c88-9b98-86446a10489c-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('69899424-0205-4407-a9b7-8bb88b7b6ac5', 'Sorriso Genuíno e Olhar', 'Movimentos', 'From 0.0s to 1.0s, in a thigh-up framing, the person stands facing forward with a wide smile, looking slightly off-camera before meeting the lens while arms rest naturally at their sides. From 1.0s to 2.5s, the person reaches their right arm forward toward the bottom corner of the frame, bringing themselves closer into view while tilting their head slightly and maintaining direct eye contact. From 2.5s to 7.833s, holding the extended selfie pose, the person stays focused on the camera with continuous warm smiling, executing subtle head tilts and minor side-to-side torso sways.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/69899424-0205-4407-a9b7-8bb88b7b6ac5.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/69899424-0205-4407-a9b7-8bb88b7b6ac5.jpg', 58, TRUE, '2026-06-15T18:57:34.86785+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'push_in', 'From 0.0s to 2.5s, the camera pushes in slightly as the hand reaches out, then holds steady with mild handheld jitter through 7.833s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/69899424-0205-4407-a9b7-8bb88b7b6ac5-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('95e13ce8-c774-4959-a242-8114c1104d48', 'Ênfase na virada de cabeça', 'Movimentos', 'From 0.0s to 2.0s, in a full-body shot, the person stands with hands rested on her waist, turning her head to the left and smiling warmly while holding a slight hip tilt. From 2.0s to 4.5s, she executes a full 360-degree spin to her right, dropping her hands slightly as her dress flares outward, sharply whipping her head and hair back toward the front. From 4.5s to 7.8s, she finishes facing forward, brings both hands back onto her waist, and holds a wide smile directly at the camera.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/95e13ce8-c774-4959-a242-8114c1104d48.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/95e13ce8-c774-4959-a242-8114c1104d48.jpg', 11, TRUE, '2026-06-15T18:54:47.535768+00:00', 'frontal', 'full-body', 'worn', TRUE, 'push_in', 'The camera slowly pushes in from full-body framing at 0.0s to a knee-up framing by 5.0s, holding static until 7.8s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/95e13ce8-c774-4959-a242-8114c1104d48-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('e5d7bd8f-1b8f-4923-a165-9669c2b38a87', 'Movimento lento + transferência de peso', 'Movimentos', 'From 0.0s to 1.0s, in a waist-up shot, the person stands facing frontally, swaying her hips side to side while maintaining a forward gaze. From 1.0s to 2.5s, she brings both hands forward to rest against her lower torso, resting her fingertips smoothly while tilting her head slightly to the left. From 2.5s to 5.0s, as the camera slowly pushes in closer, she lowers her hands to her outer hips and shifts her weight rhythmically between her legs. From 5.0s to 7.8s, she maintains a poised frontal stance with a slight head tilt to the right.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/e5d7bd8f-1b8f-4923-a165-9669c2b38a87.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/e5d7bd8f-1b8f-4923-a165-9669c2b38a87.jpg', 18, TRUE, '2026-06-15T18:55:09.268077+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'push_in', 'The camera slowly pushes in from 2.1s to 5.0s, narrowing the framing from mid-thigh to waist-up.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/e5d7bd8f-1b8f-4923-a165-9669c2b38a87-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('960ba369-65ee-421d-81e9-f50ce7a71ac2', 'Dancinha TikTok 4', 'Dancinhas', 'In a waist-up frontal shot, from 0.0s to 0.5s, the person stands still facing forward with a broad smile. From 0.5s to 2.0s, she initiates a playful dance, grooving her shoulders and torso from side to side while rhythmically pulsing her bent arms downward. From 2.0s to 4.0s, she continues swaying her hips and shoulders with dynamic energy, pouting slightly toward the camera. From 4.0s to 5.0s, she tilts her head far to the right, flashing a big smile. From 5.0s to 7.8s, she rocks her head back upright, continuing a joyful shoulder shimmy and hip sway until settling with a warm smile.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/960ba369-65ee-421d-81e9-f50ce7a71ac2.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/960ba369-65ee-421d-81e9-f50ce7a71ac2.jpg', 20, TRUE, '2026-06-15T18:55:19.397673+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', NULL, FALSE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/960ba369-65ee-421d-81e9-f50ce7a71ac2-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('bf03588b-82af-42ff-b29e-89f8ec16d130', 'Pan Lento e Zoom', 'Movimentos', 'From 0.0s to 0.7s, the camera remains perfectly stationary, holding a wide framing of shorts laid out flat on a central glass display table inside a boutique store. From 0.7s to 3.0s, the camera smoothly pushes forward in a continuous motion, moving closer to focus on the top waist area of the shorts. From 3.0s to 5.5s, the camera continues pushing in tight toward the drawstrings and center stitching. From 5.5s to 7.8s, the camera pans slightly right to highlight the white printed logo on the lower portion of the shorts.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/bf03588b-82af-42ff-b29e-89f8ec16d130.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/bf03588b-82af-42ff-b29e-89f8ec16d130.jpg', 50, TRUE, '2026-06-15T18:57:10.256656+00:00', 'frontal', 'hands', 'held', TRUE, 'push_in', 'The camera steadily pushes in toward the shorts before panning right from 0.7s to 7.8s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/bf03588b-82af-42ff-b29e-89f8ec16d130-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('d8e5ae93-e819-4889-8487-7b90fb4fd387', 'Check it Out', 'CTA', 'From 0.0s to 1.2s, the person raises both hands to chest level, pointing fingers inward toward their collarbone while looking at the camera. From 1.2s to 2.2s, they tilt their gaze downward and raise open palms to shoulder height before dropping them. From 2.2s to 4.8s, keeping their head tilted down, both index fingers point downward toward their waistline in small rhythmic bounces. From 4.8s to 5.5s, they look up back at the lens and fold both arms across their chest. From 5.5s to 7.8s, they hold the crossed-arm pose while smiling brightly. The waist-up framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/d8e5ae93-e819-4889-8487-7b90fb4fd387.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/d8e5ae93-e819-4889-8487-7b90fb4fd387.jpg', 28, TRUE, '2026-06-15T18:55:49.019586+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/d8e5ae93-e819-4889-8487-7b90fb4fd387-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('e0ff8caf-9b69-4cfb-87f3-da0756129c50', 'Ajustando o Caimento', 'Movimentos', 'From 0.0s to 1.0s, the person smiles towards the camera, then tilts their head down while lowering their gaze. From 1.0s to 3.0s, keeping their head tilted downward, both hands reach down to touch and adjust the bottom hem of their shorts. From 3.0s to 5.5s, they lift their head back up to look directly at the camera while bringing both hands up along their torso to smooth the shoulders of their vest. From 5.5s to 7.8s, they slide their hands down to their sides, raise their chin slightly, and hold a confident pose. The framing remains a static waist-up shot.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/e0ff8caf-9b69-4cfb-87f3-da0756129c50.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/e0ff8caf-9b69-4cfb-87f3-da0756129c50.jpg', 53, TRUE, '2026-06-15T18:57:21.312039+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/e0ff8caf-9b69-4cfb-87f3-da0756129c50-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('76b665de-04f9-4023-a091-2796ede95a3d', 'Espelho Relax', 'Mirror Selfie', 'From 0.0s to 0.8s, the person smiles into their reflection, holding a phone in their right hand while placing their left hand on their hip. From 0.8s to 2.2s, they hold a steady pose with a soft smile and head slightly tilted left. From 2.2s to 3.7s, the left hand lifts to run fingers through their hair on the left side, sliding down past the ear to the neck. From 3.7s to 5.0s, the left hand rests lightly against the neck beneath the jaw while the head tilts right. From 5.0s to 7.8s, the pose remains held with a gentle gaze at the screen. The framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/76b665de-04f9-4023-a091-2796ede95a3d.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/76b665de-04f9-4023-a091-2796ede95a3d.jpg', 44, TRUE, '2026-06-15T18:56:45.578388+00:00', 'mirror', 'waist-up', 'worn', TRUE, 'static', 'the framing never changes', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/76b665de-04f9-4023-a091-2796ede95a3d-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('a38f7422-c87d-4f61-97ed-2ee39bd8a049', 'Energia Alta', 'CTA', 'From 0.0s to 0.8s, she stands waist-up facing forward, smiling while stepping rhythmically. From 0.8s to 2.0s, she places her left hand on her hip and sweeps her right hand in energetic high arcs overhead while swaying her hips side to side. From 2.0s to 4.5s, her right index finger points repeatedly downward as her hips rock rhythmically. From 4.5s to 5.5s, she drops her arms before lifting them up. From 5.5s to 7.0s, she points both index fingers downward at chest height while bouncing with a broad smile. From 7.0s to 7.8s, she relaxes her arms down. The framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/a38f7422-c87d-4f61-97ed-2ee39bd8a049.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/a38f7422-c87d-4f61-97ed-2ee39bd8a049.jpg', 29, TRUE, '2026-06-15T18:55:51.989325+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/a38f7422-c87d-4f61-97ed-2ee39bd8a049-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('2b09f51d-9cf6-4bdb-99f7-116ce6439fb1', 'Selfie Aprovação', 'Selfie', 'From 0.0s to 0.8s, the person maintains direct eye contact with a soft smile in a head-and-shoulders framing. From 0.8s to 3.0s, they raise their hand beside their face and wave side to side toward the camera. From 3.0s to 7.0s, they transition into extending a clear thumbs-up gesture forward toward the lens, holding it steady while maintaining their smile. From 7.0s to 7.8s, they lower their hand out of frame while keeping their head motionless and gaze fixed on the camera. The framing never changes throughout.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/2b09f51d-9cf6-4bdb-99f7-116ce6439fb1.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/2b09f51d-9cf6-4bdb-99f7-116ce6439fb1.jpg', 37, TRUE, '2026-06-15T18:56:18.942567+00:00', 'frontal', 'head-and-shoulders', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/2b09f51d-9cf6-4bdb-99f7-116ce6439fb1-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('4609f5cd-a02c-4f6b-afdf-811b6537a42e', 'Pose de Mãos nos Bolsos', 'Movimentos', 'From 0.0s to 1.0s, in a full-body frontal shot, the person stands tall facing forward with their chin tilted slightly upward, reaching both arms down toward their waist. From 1.0s to 2.167s, they smoothly slide both hands into their side pockets. From 2.167s to 5.333s, they hold this casual posture with hands parked in pockets, maintaining a steady gaze at the camera. From 5.333s to 7.833s, they perform a subtle head nod down and back up while their body and hands stay completely still. The camera framing never changes throughout the clip.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/4609f5cd-a02c-4f6b-afdf-811b6537a42e.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/4609f5cd-a02c-4f6b-afdf-811b6537a42e.jpg', 51, TRUE, '2026-06-15T18:57:13.851477+00:00', 'frontal', 'full-body', 'worn', FALSE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/4609f5cd-a02c-4f6b-afdf-811b6537a42e-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('03477f88-fb98-4785-a43f-d6f0e251568a', 'Admirando o Produto', 'Movimentos', 'From 0.0s to 0.67s, stands facing front in a waist-up shot, smiling at the camera with arms resting at sides. From 0.67s to 1.83s, brings both hands up to chest height, placing fingertips on the upper collar area while tilting the head down to look at the outfit. From 1.83s to 3.83s, slides hands down to grip the bottom hem at the waist while keeping gaze directed downward. From 3.83s to 5.0s, drops arms to sides, raises head, and looks back at the camera with a bright smile as camera pushes in. From 5.0s to 7.83s, holds a friendly smile while standing still.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/03477f88-fb98-4785-a43f-d6f0e251568a.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/03477f88-fb98-4785-a43f-d6f0e251568a.jpg', 54, TRUE, '2026-06-15T18:57:24.146807+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'push_in', 'The camera pushes in slightly from 3.8s to 5.0s to tighten the framing.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/03477f88-fb98-4785-a43f-d6f0e251568a-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('82edf89e-26dc-4170-8683-f52dbe7d1b2c', 'Movimento impulsionado', 'Movimentos', 'From 0.0s to 1.8s, in a full-body shot, the person stands facing forward with hands resting on hips, smiling with head held steady and right leg crossed over left. From 1.8s to 3.5s, she uncrosses her legs, stepping her left foot forward to stand with feet side-by-side while keeping hands on her waist. From 3.5s to 4.5s, she sways her hips gently to the sides, tilting her head back slightly with an open smile. From 4.5s to 7.8s, she continues swaying her hips side to side in a rhythmic motion while maintaining her hands-on-hips pose and gazing forward.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/82edf89e-26dc-4170-8683-f52dbe7d1b2c.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/82edf89e-26dc-4170-8683-f52dbe7d1b2c.jpg', 12, TRUE, '2026-06-15T18:54:51.593278+00:00', 'frontal', 'full-body', 'worn', FALSE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/82edf89e-26dc-4170-8683-f52dbe7d1b2c-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('db269548-f7b3-4c82-b4eb-aa7441fd6a49', 'Esticando o Tecido', 'Movimentos', 'From 0.0s to 0.8s, the person stands facing the camera with a smile in waist-up framing. From 0.8s to 1.8s, she looks down and brings both hands to her waistband. From 1.8s to 3.0s, the camera pushes in close to her torso as her hands grasp the front waistband. From 3.0s to 5.5s, she pulls the elastic waistband sideways in a wide, firm stretch. From 5.5s to 7.8s, she releases the fabric, lowers her hands, and glances to the right while the camera pulls back out to waist-up framing.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/db269548-f7b3-4c82-b4eb-aa7441fd6a49.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/db269548-f7b3-4c82-b4eb-aa7441fd6a49.jpg', 59, TRUE, '2026-06-15T18:57:37.782354+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'push_in', 'The camera pushes in close to the waist from 1.8s and pulls back out by 7.8s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/db269548-f7b3-4c82-b4eb-aa7441fd6a49-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('9c909d32-d4cd-4216-90dd-04ba0800685b', 'Estilo UGC', 'Movimentos', 'From 0.0s to 1.0s, the person stands facing the camera with a cheerful expression and gaze fixed on the lens. From 1.0s to 2.6s, she leans her upper torso forward and down toward the camera, tilting her head left with a wide smile. From 2.6s to 3.5s, she rises back upright while extending both arms out wide to her sides. From 3.5s to 4.6s, she executes a full 360-degree spin counterclockwise, showing her back briefly before returning to face front. From 4.6s to 7.8s, she stands straight with arms relaxed at her sides, maintaining a warm smile toward the camera.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/9c909d32-d4cd-4216-90dd-04ba0800685b.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/9c909d32-d4cd-4216-90dd-04ba0800685b.jpg', 36, TRUE, '2026-06-15T18:56:14.191697+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', '{"beats": [{"end_s": 2.6, "start_s": 0, "description": "Standing initially, she leans her upper torso forward toward the camera while tilting her head toward screen left with a wide smile.", "is_defining": false}, {"end_s": 3.5, "start_s": 2.6, "description": "She returns upright while spreading both arms wide to screen left and screen right.", "is_defining": false}, {"end_s": 4.6, "start_s": 3.5, "description": "She executes a full 360-degree spin counterclockwise, showing her back briefly before returning to face front.", "is_defining": true}, {"end_s": 7.8, "start_s": 4.6, "description": "She stands straight with arms relaxed at her sides, smiling toward the camera.", "is_defining": false}], "continuity": "A cheerful expression and forward gaze are maintained throughout."}'::jsonb, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/9c909d32-d4cd-4216-90dd-04ba0800685b-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('b6e938a0-7cee-4ab4-9279-e00618d8fcdc', 'Desvio lateral lento', 'Movimentos', 'From 0.0s to 1.0s, in a waist-up framing, the person stands facing the camera with a subtle sway of the hips. From 1.0s to 2.5s, the left hand lifts up to touch near the collarbone while the head tilts slightly to the left with gaze forward. From 2.5s to 5.0s, the left fingers slowly slide down across the upper chest while the hips shift smoothly from side to side. From 5.0s to 7.0s, both hands meet at the waist level over the small bag. From 7.0s to 7.8s, the torso shifts sideways to the right with a light hip pop.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b6e938a0-7cee-4ab4-9279-e00618d8fcdc.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b6e938a0-7cee-4ab4-9279-e00618d8fcdc.jpg', 15, TRUE, '2026-06-15T18:55:00.153625+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b6e938a0-7cee-4ab4-9279-e00618d8fcdc-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('f9828453-c447-4532-82a3-4121c0b6a59e', 'Ajustando a Roupa', 'geral', 'From 0.0s to 1.3s, starting in waist-up framing, the person smiles forward while bringing both hands up toward chest height. From 1.3s to 2.8s, both hands grip the upper lapels of the vest near the collar. From 2.8s to 4.3s, fingers gently tug the collar open to adjust the neckline while gaze lowers slightly. From 4.3s to 6.3s, hands move down the front opening, adjusting each button in sequence down to the waist while head turns slightly left. From 6.3s to 7.8s, hands release the garment and lower to sides while gaze turns forward with a warm smile.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/f9828453-c447-4532-82a3-4121c0b6a59e.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/f9828453-c447-4532-82a3-4121c0b6a59e.jpg', 55, TRUE, '2026-06-15T18:57:27.066549+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'push_in', 'The camera continuously pushes in slowly from a waist-up framing to a tight upper-torso shot from 0.0s to 5.0s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/f9828453-c447-4532-82a3-4121c0b6a59e-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('eec8ad0b-1355-476d-8c68-b566cc465f06', 'Toque Sutil no Tecido', 'Movimentos', 'From 0.0s to 1.0s, the person smiles forward before tilting their head down and bringing both hands up toward the vest hem. From 1.0s to 3.5s, the fingers pinch and lightly pull the bottom hem outward while the gaze remains downward. Simultaneously, the camera performs a smooth push-in from mid-thigh to waist-up framing. From 3.5s to 5.3s, both hands release the fabric and rest flat against the front of the shorts with fingers spread. From 5.3s to 7.8s, the fingers move inward to touch and adjust the bottom button area near the waistline while the camera tilts up.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/eec8ad0b-1355-476d-8c68-b566cc465f06.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/eec8ad0b-1355-476d-8c68-b566cc465f06.jpg', 60, TRUE, '2026-06-15T18:57:40.683661+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'push_in', 'The camera smoothly pushes in from 0.0s to 3.5s and holds still until 7.8s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/eec8ad0b-1355-476d-8c68-b566cc465f06-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('b91cb3c6-65dc-479e-8b69-4db880dfea37', 'Arrumando o Cabelo', 'Movimentos', 'From 0.0s to 1.0s, the person stands facing front in a waist-up framing, holding a broad smile with gaze directed forward and arms resting relaxed at the sides. From 1.0s to 2.0s, the right arm raises up toward the head. From 2.0s to 4.8s, the right hand reaches to the top of the hair, sliding fingers smoothly down through the strands and tossing the ends outward, while the head tilts slightly right. From 4.8s to 7.8s, the right hand lowers back down to the side, and the person continues smiling while looking slightly off-camera. The framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b91cb3c6-65dc-479e-8b69-4db880dfea37.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b91cb3c6-65dc-479e-8b69-4db880dfea37.jpg', 56, TRUE, '2026-06-15T18:57:29.659357+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/b91cb3c6-65dc-479e-8b69-4db880dfea37-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('315064fe-899d-4a1a-bb82-c214c67012d8', 'Estilo de vida', 'Movimentos', 'From 0.0s to 0.8s, the person stands facing forward, swaying hips side to side as both hands raise toward the head. From 0.8s to 2.0s, hands touch the frames of the sunglasses while the head tilts back and to the right. From 2.0s to 3.0s, the hands stroke back through the hair as the head tilts left. From 3.0s to 4.5s, arms lower down to the sides while the torso rotates slightly right, head tilting upward. From 4.5s to 7.8s, the person returns centered, maintaining posture with subtle hip movement. The framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/315064fe-899d-4a1a-bb82-c214c67012d8.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/315064fe-899d-4a1a-bb82-c214c67012d8.jpg', 16, TRUE, '2026-06-15T18:55:02.870558+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/315064fe-899d-4a1a-bb82-c214c67012d8-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('9dc87cd4-1b6f-4087-aa68-e2c29c3a089e', 'Sorriso Sútil', 'Movimentos', 'In a waist-up shot, the person begins from 0.0s to 1.8s with their head tilted slightly, flashing a bright, open-mouthed smile toward the camera while holding a steady posture. From 1.8s to 4.6s, they slowly tilt their head upright and soften their expression into a quiet, closed-mouth smile while maintaining direct eye contact. From 4.6s to 5.1s, they blink softly while keeping their posture poised and relaxed. From 5.1s to 7.8s, they lift their chin slightly and hold a confident, calm expression toward the lens. The camera framing remains static throughout.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/9dc87cd4-1b6f-4087-aa68-e2c29c3a089e.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/9dc87cd4-1b6f-4087-aa68-e2c29c3a089e.jpg', 57, TRUE, '2026-06-15T18:57:32.277512+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/9dc87cd4-1b6f-4087-aa68-e2c29c3a089e-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('bd6099c6-868e-4098-83ed-19e42d2917b2', 'Giro Lento e Olhar', 'Movimentos', 'From 0.0s to 1.0s, the person stands waist-up facing slightly right, smiling directly at the camera. From 1.0s to 2.5s, they slowly pivot their body to their left until their back faces the camera, while keeping their head turned back over their left shoulder to maintain continuous eye contact. From 2.5s to 6.5s, they hold this back-to-camera pose, gazing steadily over the shoulder toward the lens with a calm expression. From 6.5s to 7.8s, they smoothly rotate their torso back around to face front, returning to the starting position while keeping their eyes on the camera. The framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/bd6099c6-868e-4098-83ed-19e42d2917b2.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/bd6099c6-868e-4098-83ed-19e42d2917b2.jpg', 61, TRUE, '2026-06-15T18:57:43.292774+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/bd6099c6-868e-4098-83ed-19e42d2917b2-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('e15bdfc8-9d2f-4749-88cf-2bdee5b5fb24', 'Dancinhas e Movimentos Rítmicos', 'Movimentos', 'From 0.0s to 1.0s, the person spreads both arms outward with bent elbows while swaying their hips. From 1.0s to 2.0s, they bring both hands near their chest, gesturing toward their upper torso while smiling at the camera. From 2.0s to 2.8s, they extend index fingers upward and rhythmically tap them near chest height. From 2.8s to 6.0s, they drop their arms to their sides and sway their hips and torso vigorously from side to side. From 6.0s to 7.8s, the side-to-side dance slows, coming to a standstill as they relax their shoulders and gaze straight ahead. The framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/e15bdfc8-9d2f-4749-88cf-2bdee5b5fb24.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/e15bdfc8-9d2f-4749-88cf-2bdee5b5fb24.jpg', 33, TRUE, '2026-06-15T18:56:06.045768+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', NULL, FALSE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/e15bdfc8-9d2f-4749-88cf-2bdee5b5fb24-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('25684f18-406e-4fee-bad1-1462a71a94c7', 'Relaxamento de ombros', 'Movimentos', 'From 0.0s to 1.5s, in a full-body view, she stands facing forward with hands resting on her hips, smiling at the camera. From 1.5s to 2.5s, she releases her hands and extends her arms outward to the sides while stepping slightly. From 2.5s to 3.8s, she reaches down to grasp the bottom edge of her dress, holding the fabric loosely. From 3.8s to 5.0s, she brings both hands together at lower waist level, clasping her fingers. From 5.0s to 7.8s, she maintains this pose, tilting her head softly to her left shoulder while smiling towards the lens.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/25684f18-406e-4fee-bad1-1462a71a94c7.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/25684f18-406e-4fee-bad1-1462a71a94c7.jpg', 9, TRUE, '2026-06-15T18:54:40.569796+00:00', 'frontal', 'full-body', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/25684f18-406e-4fee-bad1-1462a71a94c7-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('4ea4a018-7ecd-4738-95d9-dade780e298c', 'Quietude com Presença', 'Movimentos', 'From 0.0s to 0.8s, the person stands facing forward with arms at her sides, smiling directly into the camera. From 0.8s to 1.5s, she lifts both hands simultaneously and places them on her hips with elbows flared outward. From 1.5s to 7.8s, she maintains her hands on her hips in a confident pose, keeping her torso upright, head centered, and gaze fixed forward with an open smile. The camera holds a waist-up framing before panning slightly to the right between 3.5s and 4.5s and back to the left by 6.0s, remaining still through 7.8s.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/4ea4a018-7ecd-4738-95d9-dade780e298c.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/4ea4a018-7ecd-4738-95d9-dade780e298c.jpg', 5, TRUE, '2026-06-15T18:54:27.048655+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'push_in', 'The camera slowly pushes in between 3.5s and 4.5s, tightening the framing.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/4ea4a018-7ecd-4738-95d9-dade780e298c-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('7f2af940-a247-4132-a3e2-a7c26274f94a', 'Selfie Pensativo', 'Selfie', 'From 0.0s to 1.0s, in a head-and-shoulders view, the head turns slightly while the gaze shifts off-camera with a subtle smile. From 1.0s to 1.8s, the hand raises to touch the chin, resting fingers along the jawline as the head tilts back slightly and the eyes look upward. From 1.8s to 4.5s, the thoughtful pose is held with small eye movements. From 4.5s to 6.8s, the eyes close briefly, reopen, and glance off to the side. From 6.8s to 7.8s, the hand drops back down as the gaze returns directly toward the camera. The framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/7f2af940-a247-4132-a3e2-a7c26274f94a.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/7f2af940-a247-4132-a3e2-a7c26274f94a.jpg', 38, TRUE, '2026-06-15T18:56:21.248959+00:00', 'frontal', 'head-and-shoulders', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/7f2af940-a247-4132-a3e2-a7c26274f94a-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('8ccf2137-1c43-43da-abd8-fc335c907e1e', 'Espelho Casual', 'Mirror Selfie', 'Mirror selfie shot. Subject stands in front of a mirror, casually adjusting clothing. Natural posture, relaxed expression. Subtle phone movement.', NULL, NULL, 45, FALSE, '2026-06-15T18:56:46.170437+00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('2b4bd7e3-291d-42a0-93a7-b86ae011ac7f', 'Giro e "Pose" de Modelo', 'Movimentos', 'From 0.0s to 0.5s, the person stands facing front, smiling at the camera with arms relaxed at her sides. From 0.5s to 2.0s, she performs a full 360-degree spin to her left, letting her arms swing outward as her torso and jacket rotate. From 2.0s to 4.1s, she completes the turn facing forward, places her right hand on her hip, and brings her left hand up to rest lightly against the left side of her neck while holding a steady smile. From 4.1s to 7.8s, she lowers both hands to grip the front edges of her jacket at waist height, adjusting them while maintaining her forward pose.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/2b4bd7e3-291d-42a0-93a7-b86ae011ac7f.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/2b4bd7e3-291d-42a0-93a7-b86ae011ac7f.jpg', 32, TRUE, '2026-06-15T18:56:02.887378+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/2b4bd7e3-291d-42a0-93a7-b86ae011ac7f-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('0cc96e2e-88a1-413a-adab-3ca785b48bb5', 'Vem Ver', 'Movimentos', 'From 0.0s to 1.167s, the person faces front smiling, reaching both hands forward toward the camera with open palms in a beckoning motion. From 1.167s to 3.333s, she drops her hands and sways her hips side to side, stepping rhythmically with a wide smile. From 3.333s to 5.5s, she raises both hands and points index fingers inward toward her chest, grooving with active shoulder and hip bounces. From 5.5s to 7.833s, she lowers her hands into her front jeans pockets, holding a confident smile while facing forward. The framing remains static throughout.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/0cc96e2e-88a1-413a-adab-3ca785b48bb5.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/0cc96e2e-88a1-413a-adab-3ca785b48bb5.jpg', 31, TRUE, '2026-06-15T18:55:59.062202+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/0cc96e2e-88a1-413a-adab-3ca785b48bb5-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('2f5a5342-db10-4d3b-a260-5804475cd8c5', 'Caminhada Casual', 'Movimentos', 'From 0.0s to 0.8s, the person stands facing the camera, briefly clasping their hands at waist height before releasing them to their sides. From 0.8s to 2.5s, they step forward toward the lens while reaching their right arm out toward the camera. From 2.5s to 4.5s, they pause close to the camera, looking straight ahead before turning their head to the left. From 4.5s to 7.8s, they turn 180 degrees to their left and walk away from the camera down an aisle. The camera operates handheld, tracking back as the person approaches.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/2f5a5342-db10-4d3b-a260-5804475cd8c5.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/2f5a5342-db10-4d3b-a260-5804475cd8c5.jpg', 52, TRUE, '2026-06-15T18:57:18.130921+00:00', 'frontal', 'full-body', 'worn', TRUE, 'handheld', 'The handheld camera moves back as the person approaches between 0.8s and 4.5s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/2f5a5342-db10-4d3b-a260-5804475cd8c5-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('174d6ce9-91cf-4c0e-a45d-3dc6fff8c65d', 'Espera final casual', 'Movimentos', 'From 0.0s to 1.0s, the person stands facing the camera with one hand resting on the hip, smiling warmly. From 1.0s to 2.0s, the head turns slowly to the left while maintaining a wide smile. From 2.0s to 2.8s, the head turns back to face front as the hand transitions from the hip up toward the collarbone. From 2.8s to 4.8s, the hand holds near the upper chest while the face smiles directly into the lens. From 4.8s to 5.6s, the hand lowers back down. From 5.6s to 7.8s, the hand rests firmly on the hip again while holding a poised, stationary pose.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/174d6ce9-91cf-4c0e-a45d-3dc6fff8c65d.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/174d6ce9-91cf-4c0e-a45d-3dc6fff8c65d.jpg', 1, TRUE, '2026-06-15T18:54:14.971258+00:00', 'frontal', 'full-body', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/174d6ce9-91cf-4c0e-a45d-3dc6fff8c65d-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('25d1bacd-3e69-4f58-beac-ab5bbbd6fe8a', 'Dancinha TikTok 5', 'Dancinhas', 'From 0.0s to 1.0s, in a waist-up frontal shot, the person smiles directly at the camera while keeping arms relaxed at the waist. From 1.0s to 4.3s, she struts forward toward the camera, swaying her hips gently and swinging her arms in rhythm with her steps while maintaining a broad smile. From 4.3s to 7.0s, she brings her hands together at chest height and rubs her palms together repeatedly, shifting her weight side to side as her smile brightens. From 7.0s to 7.8s, she lowers her hands back down toward her sides while continuing to walk forward toward the camera. The framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/25d1bacd-3e69-4f58-beac-ab5bbbd6fe8a.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/25d1bacd-3e69-4f58-beac-ab5bbbd6fe8a.jpg', 19, TRUE, '2026-06-15T18:55:13.854609+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'static', 'The framing never changes.', NULL, FALSE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/25d1bacd-3e69-4f58-beac-ab5bbbd6fe8a-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('3b904256-2ec8-46eb-b794-31f0f4732058', 'Mudança natural de atenção', 'Movimentos', 'In a waist-up framing, from 0.0s to 2.0s, the person stands with their right hand rested on their hip, looking off-camera to their left with a warm smile. From 2.0s to 4.0s, they rotate their torso to their right, dropping their right arm while turning their head over their left shoulder to gaze directly into the camera lens. From 4.0s to 5.5s, they pivot back to face full frontal, bringing both arms down. From 5.5s to 7.8s, they place their left hand on their left hip and hold a confident, cheerful smile.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/3b904256-2ec8-46eb-b794-31f0f4732058.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/3b904256-2ec8-46eb-b794-31f0f4732058.jpg', 3, TRUE, '2026-06-15T18:54:20.720237+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'the framing never changes', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/3b904256-2ec8-46eb-b794-31f0f4732058-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('ce5eacea-880e-4a7c-8d10-8719cc64f24d', 'Olhar Curioso e Sorriso', 'Movimentos', 'From 0.0s to 0.8s, the person stands facing forward, bringing hands together across the waist in a relaxed clasp while looking directly at the camera. From 0.8s to 1.6s, they tilt their head left, cast their gaze down, and release their hands back down to their sides. From 1.6s to 2.8s, they tilt their head right with a curious expression. From 2.8s to 4.5s, they align their head center with arms resting at sides. From 4.5s to 7.8s, they break into a broad smile facing forward as the camera slowly pushes in closer.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/ce5eacea-880e-4a7c-8d10-8719cc64f24d.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/ce5eacea-880e-4a7c-8d10-8719cc64f24d.jpg', 47, TRUE, '2026-06-15T18:56:55.045824+00:00', 'frontal', 'full-body', 'worn', TRUE, 'push_in', 'The camera slowly pushes in from 0.0s to 7.8s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/ce5eacea-880e-4a7c-8d10-8719cc64f24d-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('44d1999d-2531-4923-8d3a-5ada50b1ffff', 'Foco na parte superior do corpo', 'Movimentos', 'From 0.0s to 1.8s, the person stands full-body with hands on hips, smiling at the camera and shifting weight. From 1.8s to 3.8s, the camera pushes in to waist-up framing as she keeps hands on hips and turns her head slightly to the right while looking forward. From 3.8s to 5.2s, in a close chest-up view, she tilts her head back and to the right with eyes closed in a calm expression. From 5.2s to 7.833s, she returns her head upright, lowers her arms to her sides, and smiles directly into the camera.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/44d1999d-2531-4923-8d3a-5ada50b1ffff.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/44d1999d-2531-4923-8d3a-5ada50b1ffff.jpg', 13, TRUE, '2026-06-15T18:54:54.906281+00:00', 'frontal', 'full-body', 'worn', TRUE, 'push_in', 'The camera pushes in continuously toward the person from 1.8s to 4.0s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/44d1999d-2531-4923-8d3a-5ada50b1ffff-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('1d9afe93-993a-4887-b2c2-f26dea356f0c', 'POV - Mãos Segurando o Produto', 'Movimentos', 'From 0.0s to 1.0s, both hands hold the product up in front of the camera, gently shifting it upward. From 1.0s to 2.3s, both hands hold the product steadily at center depth. From 2.3s to 5.5s, the right hand releases its grip from the right side, moves toward the center, and lightly brushes its fingertips downward across the front surface of the product. From 5.5s to 7.8s, the right hand moves back to grasp the right side, holding the product still with both hands.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/1d9afe93-993a-4887-b2c2-f26dea356f0c.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/1d9afe93-993a-4887-b2c2-f26dea356f0c.jpg', 49, TRUE, '2026-06-15T18:57:04.062958+00:00', 'pov', 'hands', 'held', FALSE, 'static', 'The framing never changes.', '{"beats": [{"end_s": 2.167, "start_s": 0, "description": "Both hands hold the top edges of a wooden hanger displaying shorts.", "is_defining": false}, {"end_s": 5.5, "start_s": 2.167, "description": "The screen-right hand releases its hold and reaches out to gently tap and stroke the fabric surface of the shorts.", "is_defining": true}, {"end_s": 7.833, "start_s": 5.5, "description": "The screen-right hand returns to grip the wooden hanger, holding it steadily with both hands.", "is_defining": false}], "continuity": "The screen-left hand maintains its grip on the hanger throughout."}'::jsonb, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/1d9afe93-993a-4887-b2c2-f26dea356f0c-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('5c2906f5-8536-4985-a86b-f1195c600ee0', 'Convite Amigável', 'CTA', 'In a waist-up framing, from 0.0s to 0.833s, she stands smiling directly at the camera. From 0.833s to 1.333s, she raises both hands and points her index fingers inward toward her chest. From 1.333s to 3.333s, she shifts her hands downward, pointing her index fingers toward her waist while smiling widely. From 3.333s to 5.333s, she brings both hands up to shoulder level and points both index fingers downwards, pulsing them rhythmically in place. From 5.333s to 6.0s, she lowers her arms back down to her sides. From 6.0s to 7.833s, she holds a steady smile. The framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/5c2906f5-8536-4985-a86b-f1195c600ee0.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/5c2906f5-8536-4985-a86b-f1195c600ee0.jpg', 30, TRUE, '2026-06-15T18:55:55.324413+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/5c2906f5-8536-4985-a86b-f1195c600ee0-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('d4640d2e-fa34-40f4-9e58-5ed34415b99b', 'Auto confiança', 'Movimentos', 'From 0.0s to 1.3s, the person stands facing forward in a full-body view with hands resting firmly on their hips, legs crossed at the ankles, smiling with gaze fixed on the camera. From 1.3s to 2.1s, they uncross their legs and stand with feet close together while keeping hands planted on the waist. From 2.1s to 7.8s, stepping into a wider stance with hands on hips, they gently sway their hips and torso side to side with subtle head tilts and an open smile. The camera slowly pushes in from 0.0s to 7.8s, shifting framing from full body to three-quarters.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/d4640d2e-fa34-40f4-9e58-5ed34415b99b.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/d4640d2e-fa34-40f4-9e58-5ed34415b99b.jpg', 10, TRUE, '2026-06-15T18:54:43.196142+00:00', 'frontal', 'full-body', 'worn', FALSE, 'push_in', 'The camera slowly pushes in continuously from 0.0s to 7.8s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/d4640d2e-fa34-40f4-9e58-5ed34415b99b-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('9e64fe99-e3fd-45bb-9734-fa91bdd1729c', 'Selfie Aponta', 'Selfie', 'From 0.0s to 1.0s, head tilts right, looking forward with a relaxed smile while left hand grips jacket lapel. From 1.0s to 2.8s, eyes blink softly and reopen as smile widens while left hand adjusts the jacket edge outward. From 2.8s to 4.5s, left index finger points directly at chest while head turns slightly left and gaze stays forward. From 4.5s to 6.3s, left hand pulls back briefly before pointing at chest again with an open smile. From 6.3s to 7.8s, left hand lowers, head tilts right, and eyes close gently at the end. Framing stays constant throughout.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/9e64fe99-e3fd-45bb-9734-fa91bdd1729c.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/9e64fe99-e3fd-45bb-9734-fa91bdd1729c.jpg', 39, TRUE, '2026-06-15T18:56:24.395977+00:00', 'frontal', 'head-and-shoulders', 'worn', TRUE, 'handheld', 'The camera is held in a selfie position with slight natural handheld movement throughout.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/9e64fe99-e3fd-45bb-9734-fa91bdd1729c-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('a81b0eb1-dda0-43fc-a760-6752c41f1198', 'Ênfase na altura da cintura', 'Movimentos', 'From 0.0s to 1.3s, the person stands facing the camera with a wide smile, arms resting at her sides. From 1.3s to 2.8s, she shifts her hips and brings her left hand up to rest on her left hip. From 2.8s to 5.0s, as the camera pushes in, she brings her right hand up to place on her right waist. From 5.0s to 6.8s, with both hands on her waist, she turns her torso slightly to the left to pose while keeping her gaze fixed on the camera. From 6.8s to 7.8s, she rotates her torso back toward the front, holding her hands on her waist.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/a81b0eb1-dda0-43fc-a760-6752c41f1198.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/a81b0eb1-dda0-43fc-a760-6752c41f1198.jpg', 6, TRUE, '2026-06-15T18:54:30.609106+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'push_in', 'The camera pushes in closer from 0.0s to 5.0s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/a81b0eb1-dda0-43fc-a760-6752c41f1198-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('d49f1301-1988-4599-abaa-30a94c6a42f6', 'Espelho Textura', 'Mirror Selfie', 'From 0.0s to 1.5s, in a waist-up mirror view, she looks forward with a smile, raising her left hand to place her fingertips on her upper chest. From 1.5s to 3.0s, the camera pushes in closer as her gaze drops slightly, and her fingers gently stroke across her collarbone area. From 3.0s to 6.0s, she continues lightly tapping her chest with her left hand while maintaining a soft smile. From 6.0s to 7.8s, the camera pulls back out to the original framing as she lowers her left hand and looks directly back into the lens.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/d49f1301-1988-4599-abaa-30a94c6a42f6.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/d49f1301-1988-4599-abaa-30a94c6a42f6.jpg', 43, TRUE, '2026-06-15T18:56:39.870914+00:00', 'mirror', 'waist-up', 'worn', TRUE, 'push_in', 'The camera pushes in closer from 1.8s to 3.0s and pulls back out between 6.0s and 7.8s.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/d49f1301-1988-4599-abaa-30a94c6a42f6-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('bcafc353-8fcf-4d81-95ab-9bcf3fe94901', 'Selfie Sorriso', 'Selfie', 'In a close-up selfie framing, from 0.0s to 1.0s, the person smiles into the camera and winks with her right eye while gripping her jacket lapel with her left hand. From 1.0s to 2.333s, she tilts her head toward her shoulder and gently strokes the collar with her fingers, closing her eyes briefly. From 2.333s to 5.0s, she holds the jacket lapel near her chest, smiling warmly into the lens while making minor head tilts. From 5.0s to 7.833s, she releases the collar, drops her hand, and continues smiling at the camera with occasional blinks. The camera experiences subtle handheld shake throughout.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/bcafc353-8fcf-4d81-95ab-9bcf3fe94901.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/bcafc353-8fcf-4d81-95ab-9bcf3fe94901.jpg', 41, TRUE, '2026-06-15T18:56:32.25982+00:00', 'frontal', 'head-and-shoulders', 'worn', TRUE, 'handheld', 'The camera experiences slight handheld movement throughout the clip.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/bcafc353-8fcf-4d81-95ab-9bcf3fe94901-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('c0787327-ecb5-48dc-938a-8951d3e5c38d', 'Dancinha TikTok 3', 'Dancinhas', 'From 0.0s to 0.667s, the person smiles at the camera, raising both hands to chest height to form a heart shape with their fingers. From 0.667s to 2.5s, they cross their forearms at chest level, rolling their wrists repeatedly while swaying their shoulders and torso side to side. From 2.5s to 3.833s, they lower their arms and continue swaying rhythmically with a broad smile. From 3.833s to 5.5s, they extend both arms straight forward, pointing index fingers directly at the camera. From 5.5s to 7.833s, they pull their hands back, pointing both index fingers inward at their chest. Waist-up framing; camera remains static throughout.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/c0787327-ecb5-48dc-938a-8951d3e5c38d.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/c0787327-ecb5-48dc-938a-8951d3e5c38d.jpg', 21, TRUE, '2026-06-15T18:55:24.672893+00:00', 'frontal', 'waist-up', 'worn', FALSE, 'static', 'The framing never changes.', NULL, FALSE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/c0787327-ecb5-48dc-938a-8951d3e5c38d-scene.webp') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.movement_templates (id, title, category, prompt, video_url, thumbnail_url, sort_order, is_active, created_at, shot, visible_body, product_placement, hands_free, camera, camera_note, beats, motion_clone_enabled, scene_url) VALUES ('c290a1ce-02cd-4170-adcd-6a920397a09f', 'Movimento Lateral Sutil', 'Movimentos', 'From 0.0s to 1.3s, the person smiles while placing both hands on their hips, turning gaze toward the camera. From 1.3s to 2.6s, they maintain the pose with hands on hips, smiling cheerfully. From 2.6s to 4.0s, they slide their hands down to their sides while shifting weight and swaying hips rhythmically. From 4.0s to 5.5s, they tilt their head back and to the left, closing their eyes slightly while keeping a soft smile. From 5.5s to 7.8s, they return their head upright, glance right, then gaze back directly into the lens. The waist-up framing never changes.', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/c290a1ce-02cd-4170-adcd-6a920397a09f.mp4', 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/c290a1ce-02cd-4170-adcd-6a920397a09f.jpg', 62, TRUE, '2026-06-15T18:57:46.304019+00:00', 'frontal', 'waist-up', 'worn', TRUE, 'static', 'The framing never changes.', NULL, TRUE, 'https://omlwqrtqivqcgrrlrlzf.supabase.co/storage/v1/object/public/movement-templates/c290a1ce-02cd-4170-adcd-6a920397a09f-scene.webp') ON CONFLICT (id) DO NOTHING;
